import React, { useEffect, useRef } from "react";
import { Chart, registerables } from "chart.js"; // Import registerables along with Chart

const BarChart = ({ data }) => {
  const chartRef = useRef(null);

  useEffect(() => {
    // Register necessary scale(s)
    Chart.register(...registerables);

    // Extracting data for the chart
    const labels = Object.keys(data);
    const datasets = Object.values(data).map((hospitalData) => ({
      label: hospitalData[9].hospitalName,
      data: Object.values(hospitalData).map((item) => item.actualAvailability),
      backgroundColor: "rgba(75,192,192,0.2)",
      borderColor: "rgba(75,192,192,1)",
      borderWidth: 1,
    }));

    // Creating the chart
    const ctx = chartRef.current.getContext("2d");
    new Chart(ctx, {
      type: "bar",
      data: {
        labels,
        datasets,
      },
      options: {
        scales: {
          y: {
            type: 'linear', // Specify the scale type
            beginAtZero: true,
          },
        },
      },
    });
  }, [data]);

  return <canvas ref={chartRef} />;
};

export default BarChart;
